-- ==============================================================================
-- UNIFIED MASTER PRODUCTION SEED: 227 REAL SHOP ITEMS & FAST FOOD MENU
-- Combines:
-- 1. populate_50_items.sql (Snacks, Chocolates, Beverages, Biscuits)
-- 2. populate_extra_50_items.sql (Kiryana, Dairy, Mandi Fresh Produce)
-- 3. populate_last_50_items.sql (Personal Care, Stationery, Essentials)
-- 4. seed_fast_food_shop_items.sql (Campus Mart Fast Food & Fresh Kitchen Menu)
-- 
-- Features:
-- - Real GS1 Indian EAN-13 barcodes (890xxxxxx) & clean scan-ready codes
-- - Authentic HSN / SAC codes & GST rates
-- - Cost prices (wholesale) & stock quantities
-- - Nutritional facts JSONB, allergen tags, package types
-- - Clean conflict handling (ON CONFLICT DO UPDATE)
-- ==============================================================================

-- 1. Schema Extensions
ALTER TABLE public.shop_items ADD COLUMN IF NOT EXISTS barcode text;
ALTER TABLE public.shop_items ADD COLUMN IF NOT EXISTS hsn_code text;
ALTER TABLE public.shop_items ADD COLUMN IF NOT EXISTS tax_rate double precision DEFAULT 5.0;
ALTER TABLE public.shop_items ADD COLUMN IF NOT EXISTS cost_price double precision;
ALTER TABLE public.shop_items ADD COLUMN IF NOT EXISTS is_tax_inclusive boolean DEFAULT true;
ALTER TABLE public.shop_items ADD COLUMN IF NOT EXISTS min_stock_alert integer DEFAULT 5;
ALTER TABLE public.shop_items ADD COLUMN IF NOT EXISTS package_type text;
ALTER TABLE public.shop_items ADD COLUMN IF NOT EXISTS weight_ml text;
ALTER TABLE public.shop_items ADD COLUMN IF NOT EXISTS ingredients text;
ALTER TABLE public.shop_items ADD COLUMN IF NOT EXISTS how_to_use text;
ALTER TABLE public.shop_items ADD COLUMN IF NOT EXISTS shelf_life text;
ALTER TABLE public.shop_items ADD COLUMN IF NOT EXISTS nutritional_info jsonb;

-- Pre-cleanse any previous fast food records to avoid sku_qr or id unique constraint collisions
DELETE FROM public.shop_items WHERE sku_qr LIKE 'ff_%' OR barcode LIKE 'ff_%' OR id::text LIKE 'a0000000-0000-0000-0000-00000000018%' OR id::text LIKE 'a0000000-0000-0000-0000-00000000019%' OR id::text LIKE 'a0000000-0000-0000-0000-0000000002%';

